// Generate all category+page combinations to crawl
const MAX_PAGES = parseInt($env.OLX_MAX_PAGES || '3', 10);
const REGION_ID = $env.OLX_REGION_ID || '';

const categories = [
  { name: 'apartments_sale', path: '/nedvizhimost/kvartiry/prodazha/' },
  { name: 'apartments_rent', path: '/nedvizhimost/kvartiry/arenda/' },
  { name: 'houses',          path: '/nedvizhimost/doma/' },
  { name: 'land',            path: '/nedvizhimost/zemlja/' },
  { name: 'commercial',      path: '/nedvizhimost/kommercheskie-pomeshcheniya/' }
];

// Reset run counters in persistent static data
const sd = $getWorkflowStaticData('global');
sd.run_started = new Date().toISOString();
sd.pages_crawled = 0;
sd.urls_found = 0;
sd.dedup_skipped = 0;
sd.gemini_valid = 0;
sd.gemini_invalid = 0;

const items = [];
for (const cat of categories) {
  for (let page = 1; page <= MAX_PAGES; page++) {
    let url = 'https://www.olx.uz' + cat.path;
    const params = [];
    if (page > 1) params.push('page=' + page);
    if (REGION_ID) params.push('search%5Bdistrict_id%5D=' + REGION_ID);
    if (params.length > 0) url += '?' + params.join('&');
    items.push({ json: { category: cat.name, page, url } });
  }
}

return items;

// Extract listing URLs from OLX category page HTML
const html = $input.first().json.data || '';
const category = $input.first().json.category;
const MAX_PER_PAGE = parseInt($env.OLX_MAX_LISTINGS_PER_PAGE || '40', 10);

const sd = $getWorkflowStaticData('global');
sd.pages_crawled = (sd.pages_crawled || 0) + 1;

if (!html || html.length < 500) {
  return [];  // Empty or error page
}

const seen = new Set();
const items = [];

const relPattern = /href=["'](\/d\/obyavlenie\/[^"']+)["']/g;
let match;
while ((match = relPattern.exec(html)) !== null) {
  const full = 'https://www.olx.uz' + match[1];
  if (seen.has(full)) continue;
  seen.add(full);
  const idMatch = full.match(/-(ID[a-zA-Z0-9]+)\.html/);
  if (idMatch) {
    items.push({ json: { url: full, listing_id: idMatch[1], category } });
  }
}

const absPattern = /href=["'](https:\/\/www\.olx\.uz\/d\/obyavlenie\/[^"']+)["']/g;
while ((match = absPattern.exec(html)) !== null) {
  const full = match[1];
  if (seen.has(full)) continue;
  seen.add(full);
  const idMatch = full.match(/-(ID[a-zA-Z0-9]+)\.html/);
  if (idMatch) {
    items.push({ json: { url: full, listing_id: idMatch[1], category } });
  }
}

const escPattern = /href=\\["'](\/d\/obyavlenie\/[^\\]+)\\["']/g;
while ((match = escPattern.exec(html)) !== null) {
  const full = 'https://www.olx.uz' + match[1];
  if (seen.has(full)) continue;
  seen.add(full);
  const idMatch = full.match(/-(ID[a-zA-Z0-9]+)\.html/);
  if (idMatch) {
    items.push({ json: { url: full, listing_id: idMatch[1], category } });
  }
}

const result = items.slice(0, MAX_PER_PAGE);
sd.urls_found = (sd.urls_found || 0) + result.length;
return result;

// Persistent dedup: skip OLX IDs crawled within the TTL window
const sd = $getWorkflowStaticData('global');
const TTL_HOURS = parseInt($env.OLX_DEDUP_TTL_HOURS || '168', 10);
const now = Date.now();
const ttlMs = TTL_HOURS * 3600 * 1000;

if (!sd.dedup_cache) sd.dedup_cache = {};
const cache = sd.dedup_cache;

// Evict expired entries
for (const id in cache) {
  if (now - cache[id] > ttlMs) delete cache[id];
}

// Filter items
const items = $input.all();
const output = [];
let skipped = 0;

for (const item of items) {
  const olxId = item.json.listing_id;
  if (cache[olxId]) {
    skipped++;
  } else {
    cache[olxId] = now;
    output.push(item);
  }
}

// Bound cache to 5000 entries (FIFO eviction)
const ids = Object.keys(cache);
if (ids.length > 5000) {
  ids.sort((a, b) => cache[a] - cache[b]);
  const remove = ids.length - 5000;
  for (let i = 0; i < remove; i++) delete cache[ids[i]];
}

sd.dedup_skipped = (sd.dedup_skipped || 0) + skipped;

return output;

// Convert HTML to clean text for Gemini + extract images
const html = $input.first().json.data || '';
const url = $input.first().json.url;
const listing_id = $input.first().json.listing_id;
const category = $input.first().json.category;

if (!html || html.length < 500) {
  return [{ json: { _skip: true, listing_id, url, reason: 'empty_page' } }];
}

let text = html
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const imagePattern = /src="(https:\/\/[^"]*apollo\.olxcdn\.com[^"]+)"/g;
const images = [];
const seenImgs = new Set();
let imgMatch;
while ((imgMatch = imagePattern.exec(html)) !== null) {
  let imgUrl = imgMatch[1];
  imgUrl = imgUrl.replace(/;s=\d+x\d+/, ';s=1024x768');
  if (!seenImgs.has(imgUrl)) {
    seenImgs.add(imgUrl);
    images.push(imgUrl);
  }
}

if (images.length === 0) {
  return [{ json: { _skip: true, listing_id, url, reason: 'no_images' } }];
}

return [{
  json: {
    _skip: false,
    url,
    listing_id,
    category,
    text_content: text.substring(0, 6000),
    images: images.slice(0, 12),
    raw_html_length: html.length
  }
}];

// Parse Gemini response, merge with carried metadata, normalize enums
const input = $input.first().json;
const meta = input._meta || {};
const sd = $getWorkflowStaticData('global');

const geminiText = input.candidates?.[0]?.content?.parts?.[0]?.text || '';

let jsonStr = geminiText
  .replace(/```json\s*/g, '')
  .replace(/```\s*/g, '')
  .trim();

let extracted;
try {
  extracted = JSON.parse(jsonStr);
} catch (e) {
  sd.gemini_invalid = (sd.gemini_invalid || 0) + 1;
  return [{
    json: {
      _valid: false,
      _error: 'gemini_parse_failed',
      _raw_response: geminiText.substring(0, 500),
      listing_id: meta.listing_id,
      url: meta.url
    }
  }];
}

// Enum normalization
const LT_MAP = { 'sale': 'sell', 'daily_rent': 'rent' };
const PT_MAP = { 'office': 'commercial' };

let lt = (extracted.listing_type || '').toLowerCase();
if (LT_MAP[lt]) lt = LT_MAP[lt];
if (!['sell', 'rent'].includes(lt)) {
  if (meta.category && /rent/i.test(meta.category)) lt = 'rent';
  else lt = 'sell';
}

let pt = (extracted.property_type || '').toLowerCase();
if (PT_MAP[pt]) pt = PT_MAP[pt];
if (!['apartment', 'house', 'commercial', 'land'].includes(pt)) {
  if (/house/i.test(meta.category || '')) pt = 'house';
  else if (/land/i.test(meta.category || '')) pt = 'land';
  else if (/commercial/i.test(meta.category || '')) pt = 'commercial';
  else pt = 'apartment';
}

const price = parseFloat(extracted.price);
if (!price || price <= 0) {
  sd.gemini_invalid = (sd.gemini_invalid || 0) + 1;
  return [{
    json: {
      _valid: false,
      _error: 'invalid_price',
      listing_id: meta.listing_id,
      url: meta.url
    }
  }];
}

let currency = (extracted.currency || 'USD').toUpperCase();
if (!['USD', 'UZS'].includes(currency)) currency = 'USD';

let phone = extracted.contact_phone || null;
if (phone) {
  phone = phone.replace(/[\s\-()]/g, '');
  if (/^998/.test(phone)) phone = '+' + phone;
  if (!/^\+998\d{9}$/.test(phone)) phone = null;
}

sd.gemini_valid = (sd.gemini_valid || 0) + 1;

const listing = {
  _valid: true,
  olx_id: meta.listing_id,
  url: meta.url,
  crawled_at: new Date().toISOString(),
  property_type: pt,
  listing_type: lt,
  price: price,
  currency: currency,
  rooms: extracted.rooms ? parseInt(extracted.rooms, 10) : null,
  area_sqm: extracted.area_sqm ? parseFloat(extracted.area_sqm) : null,
  floor: extracted.floor ? parseInt(extracted.floor, 10) : null,
  total_floors: extracted.total_floors ? parseInt(extracted.total_floors, 10) : null,
  district: extracted.district || null,
  address: extracted.address || null,
  description: extracted.description ? extracted.description.substring(0, 5000) : null,
  amenities: Array.isArray(extracted.amenities) ? extracted.amenities : null,
  contact_phone: phone,
  images: meta.images || [],
  source: 'olx_uz',
  seller_type: ['business', 'private'].includes(extracted.seller_type) ? extracted.seller_type : null,
  seller_name: extracted.seller_name || null,
  views_count: extracted.views_count ? parseInt(extracted.views_count, 10) : null,
  posted_date: extracted.posted_date || null,
  building_type: extracted.building_type || null,
  condition: extracted.condition || null,
  furnishing: extracted.furnishing || null,
  ceiling_height: extracted.ceiling_height ? parseFloat(extracted.ceiling_height) : null,
  bathroom: extracted.bathroom || null,
  raw_text: (meta.text_content || '').substring(0, 10000),
  original_language: ['ru', 'uz'].includes(extracted.original_language) ? extracted.original_language : 'ru'
};

return [{ json: listing }];

// Collect all valid listings, chunk into batches of 50 for backend
const allItems = $input.all();
const BATCH_SIZE = 50;

const listings = allItems.map(item => {
  const { _valid, _error, _raw_response, ...rest } = item.json;
  return rest;
});

if (listings.length === 0) {
  // Output a no-op item so the summary still fires downstream
  return [{ json: { _noop: true, payload: { listings: [] }, count: 0 } }];
}

const batches = [];
for (let i = 0; i < listings.length; i += BATCH_SIZE) {
  batches.push(listings.slice(i, i + BATCH_SIZE));
}

return batches.map(batch => ({
  json: {
    _noop: false,
    payload: { listings: batch },
    count: batch.length
  }
}));

// Aggregate all backend responses + staticData counters into a summary
const sd = $getWorkflowStaticData('global');
const responses = $input.all();

let db_created = 0, db_updated = 0, db_duplicates = 0, db_errors = 0;
for (const r of responses) {
  const d = r.json;
  db_created += d.created || 0;
  db_updated += d.updated || 0;
  db_duplicates += d.duplicates || 0;
  db_errors += d.errors || 0;
}

const duration = sd.run_started
  ? Math.round((Date.now() - new Date(sd.run_started).getTime()) / 1000)
  : 0;

const summary = {
  run_started: sd.run_started || 'unknown',
  duration_seconds: duration,
  pages_crawled: sd.pages_crawled || 0,
  urls_found: sd.urls_found || 0,
  dedup_skipped: sd.dedup_skipped || 0,
  sent_to_gemini: (sd.gemini_valid || 0) + (sd.gemini_invalid || 0),
  gemini_valid: sd.gemini_valid || 0,
  gemini_invalid: sd.gemini_invalid || 0,
  db_created,
  db_updated,
  db_duplicates,
  db_errors
};

// Build Telegram message
const msg = '<b>OLX Crawler Run Complete</b>\n'
  + '\n'
  + '<b>Coverage</b>\n'
  + 'Pages crawled: ' + summary.pages_crawled + '\n'
  + 'URLs found: ' + summary.urls_found + '\n'
  + 'Dedup skipped: ' + summary.dedup_skipped + '\n'
  + '\n'
  + '<b>Extraction</b>\n'
  + 'Sent to Gemini: ' + summary.sent_to_gemini + '\n'
  + 'Valid: ' + summary.gemini_valid + '\n'
  + 'Invalid: ' + summary.gemini_invalid + '\n'
  + '\n'
  + '<b>Database</b>\n'
  + 'Created: ' + summary.db_created + '\n'
  + 'Updated: ' + summary.db_updated + '\n'
  + 'Duplicates: ' + summary.db_duplicates + '\n'
  + 'Errors: ' + summary.db_errors + '\n'
  + '\n'
  + 'Duration: ' + summary.duration_seconds + 's';

// Check if Telegram alert is configured
const botToken = $env.ALERT_TELEGRAM_BOT_TOKEN || '';
const chatId = $env.ALERT_TELEGRAM_CHAT_ID || '';

if (!botToken || !chatId) {
  // No alert configured, return summary only (no downstream Telegram call)
  return [];
}

return [{
  json: {
    summary,
    bot_token: botToken,
    chat_id: chatId,
    message: msg
  }
}];
